c.STDIO:
#include <stdio.h>

int main(void) {
    int year, month, day;
    scanf("%d%d%d", &year, &month, &day);
    int lengths[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)) {
        lengths[1] = 29;
    }
    day++;
    if (day > lengths[month - 1]) {
        day = 1;
        month++;
    }
    if (month > 12) {
        month = 1;
        year++;
    }
    printf("%d %d %d\n", year, month, day);
    return 0;
}

